-- 0145: step 6 housekeeping + the rest of the government rows rooted in the lexicons.
-- 1. The 18 cited government rows (TDY:QR:*) carried only a Qurʾān verse. Each gets display_json.sources (book, block,
--    page, short quote — the backlink); the screen shows plain English. Fixed glosses (plain_en): شَدَّ عَلَى (10:88)
--    "seal", not "harden"; صَارَ إِلَى "end up at", not "with"; عَلِمَ … مِنْ — the مِنْ is مِمَّنْ's; قَبِلَ … عَنْ without
--    "passing over the sin"; عَزَّ فِي "in argument". نَزَّلَ بِهِ (7:33) kept, marked as from tafsīr.
-- 2. Old sense attestations of the 13 roots linked to the lexicon block they quote (block_id), matched on the
--    quote's words with diacritics removed. Not linked: translations, tafsīr and Sinai (no lexicon block) and 31
--    lexicon quotes whose words are not in that book's blocks for the root (paraphrases) — left for review.
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_4133ac08d1677d7c", "page": 233, "quote": "وتابَ إِلَى اللهِ ... أَنابَ ورَجَعَ عَنِ المَعْصيةِ إِلَى الطاعة"}, {"source": "jawhari_sihah", "block_id": "blk_sih_17031c4d9574309d", "page": 166, "quote": "وتاب إلى الله توبةً ومتاباً"}, {"source": "lane_lexicon", "block_id": "blk_lane_d499265863bca32a", "page": 321, "quote": "تاب إلى الله ... originally, he returned unto God ... from sin"}]')) WHERE id = 'TDY:QR:SP:SV:توب:I:15';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_f6ea74da3c384e61", "page": 321, "quote": "تاب الله عليه God returned to forgiveness towards him ... accepted his repentance"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_2f61478ed716f946", "page": 233, "quote": "يَتُوبُ عَلَى عَبْدِه بفَضْله إِذَا تابَ إليهِ مِنْ ذَنْبه"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_b02b773455da4f5e", "page": 78, "quote": "يَتُوبُ (عَلَى عِبَادِه) بفَضْله إِذَا تَابَ إِليه منْ ذَنْبِه"}]'), '$.note_en', 'al-Jawharī also reads تاب الله عليه as "God helped him to repent" (وفقه لها).') WHERE id = 'TDY:QR:SP:SV:توب:I:16';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_cc65a837c0a94f72", "page": 1516, "quote": "واشدد على قلوبهم ... means And put Thou a seal upon their hearts"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_f4fcd938e6834ae9", "page": 1674, "quote": "وَاشْدُدْ عَلى قُلُوبِهِمْ؛ أَي اطْبَعْ عَلَى قُلُوبِهِم"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_ec6dccbf42b53d11", "page": 247, "quote": "وَاشْدُدْ عَلَى قُلُوبِهِمْ﴾ أَي اطْبَع على قُلُوبهم"}]'), '$.plain_en', 'to seal (their hearts) shut', '$.note_en', 'The books read 10:88 as «اطبع على قلوبهم», seal; "press hard on" belongs to Form II شدّد عليه.') WHERE id = 'TDY:QR:SP:SV:شدد:I:nasara:17';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_73dd3f1132a4a38a", "page": 1674, "quote": "شَدَّ اللَّهُ مُلْكَه: وشَدَّدَه: قَوَّاه"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_d3791c1a05e270cc", "page": 1674, "quote": "وَقَالَ تَعَالَى: اشْدُدْ بِهِ أَزْرِي"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_36aefadba98c080b", "page": 241, "quote": "الشَّدُّ: التَّقْوِيَةُ ... شَدَّ اللهُ مُلْكَه أَي قَوَّاه"}]'), '$.note_en', 'The books give "strengthen" and quote 20:31; none explains the بِ.') WHERE id = 'TDY:QR:SP:SV:شدد:I:nasara:18';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_9fbfd2d8b2782dc6", "page": 1519, "quote": "هو شديد على قومه [He is hard, or severe, or rigorous, to his people]"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_33efc7e3ad2b07b2", "page": 1674, "quote": "وَرَجُلٌ شديدٌ: قويٌّ، وَالْجَمْعُ أَشِدّاء"}]')) WHERE id = 'TDY:QR:SP:SV:شدد:I:daraba:19';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_435bcbb7e3f6c1a1", "page": 1754, "quote": "ألا إلى الله تصير الأمور ... Verily to God are things ... referrible"}, {"source": "fayyumi_misbah_munir", "block_id": "blk_msb_01a58ba5866f25be", "page": 1791, "quote": "وَصَارَ الْأَمْرُ إلَى كَذَا رَجَعَ إلَيْهِ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_d74d1998e1bf8cfd", "page": 498, "quote": "وصَارَ إلى كذا: انتهى إليه"}]'), '$.plain_en', 'to come back to, to end up at') WHERE id = 'TDY:QR:SP:SV:صير:I:22';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_1f99f468db43f617", "page": 1894, "quote": "طال عليهم الأمد ... means The time became extended ... unto them"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_c94adcdbd7d1a907", "page": 533, "quote": "... كالزّمان ... قال تعالى: فَطالَ عَلَيْهِمُ الْأَمَد"}]'), '$.note_en', 'Not the other طال عليه, "did him a favour" (al-Ṣiḥāḥ p.3472).') WHERE id = 'TDY:QR:SP:SV:طول:I:21';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_f290d0022f9db725", "page": 563, "quote": "عَزَّ عَلَيَّ كذا: صَعُبَ، قال: عَزِيزٌ عَلَيْهِ ما عَنِتُّم"}, {"source": "lane_lexicon", "block_id": "blk_lane_72c63ac730f5db54", "page": 2029, "quote": "عزّ عليّ كذا Such a thing distressed, or afflicted, me"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_1964482f58cbb9c1", "page": 2958, "quote": "عَزَّ عليَّ ... أَي يشتدُّ وَيَشُقُّ علي"}]')) WHERE id = 'TDY:QR:SP:SV:عزز:I:daraba:7';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_f290d0022f9db725", "page": 563, "quote": "عَزَّ عَلَيَّ كذا: صَعُبَ"}, {"source": "maqayis_lugha", "block_id": "blk_mqy_0460496cceae2186", "page": 13, "quote": "عَزَّ عليَّ كذا، أي اشتد"}, {"source": "lane_lexicon", "block_id": "blk_lane_973f2ed820125c5a", "page": 2032, "quote": "عزيز also signifies Severe, difficult, distressing, or grievous"}]'), '$.note_en', 'Backed through the verb عَزَّ عَلَى; no book comments on 14:20.') WHERE id = 'TDY:QR:SP:SV:عزز:I:daraba:8';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_1c00032d474e4f82", "page": 2958, "quote": "وَعَزَّنِي فِي الْخِطابِ؛ أَي غَلَبَنِي فِي الِاحْتِجَاج"}, {"source": "lane_lexicon", "block_id": "blk_lane_e3dd3354e6748ac6", "page": 2031, "quote": "عزّه في الخطاب ... he overcame him in argumentative contest"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_032c52f08b8866fd", "page": 221, "quote": "عَزَّه فِي الخِطاب، أَي غَلَبَه فِي الاحْتِجاج"}]'), '$.plain_en', 'to beat someone in argument') WHERE id = 'TDY:QR:SP:SV:عزز:I:nasara:9';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_12dc1ad47a01ae73", "page": 2099, "quote": "فعاقبوا بمثل ما عوقبتم به [then punish ye with the like of that]"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_4f82fb683d7e3c75", "page": 575, "quote": "وَإِنْ عاقَبْتُمْ فَعاقِبُوا بِمِثْلِ ما عُوقِبْتُمْ بِه"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_59c16f78a16b0432", "page": 611, "quote": "وعاقَبه بِذَنْبِهِ معاقَبة وعِقاباً: أَخَذَه بِه"}]')) WHERE id = 'TDY:QR:SP:SV:عقب:III:20';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "zabidi_taj_arus", "block_id": "blk_taj_523cdf4c631affa0", "page": 126, "quote": "إنَّما يَتَعَدَّى بالباءِ؛ لأنَّه يُراعَى فِيهِ أَحْيَانًا مَعْنَى الإحاطَة"}, {"source": "lane_lexicon", "block_id": "blk_lane_3ba7a1bd06647d11", "page": 2138, "quote": "followed by ب ... علم به ... he knew, or had knowledge, of it"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_3d2a9b7d2053951a", "page": 1751, "quote": "وعَلِمَ بِالشَّيْءِ: شَعَر"}]'), '$.note_en', 'Tāj: بِ carries "taking it all in" (الإحاطة).') WHERE id = 'TDY:QR:SP:SV:علم:I:10';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "zabidi_taj_arus", "block_id": "blk_taj_2acf4b861bca7328", "page": 127, "quote": "صِفَةٌ توجِبُ تَمْييزًا لَا يحتَمِلُ النَّقيض"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_6ad85f9fbe677008", "page": 580, "quote": "العِلْمُ: إدراك الشيء بحقيقته"}]'), '$.plain_en', 'to know (and so tell apart)', '$.note_en', 'The مِنْ belongs to مِمَّنْ ("from among"), not to the verb; no book has عَلِمَ with مِنْ. "Tell apart" is from tafsīr (2:143).') WHERE id = 'TDY:QR:SP:SV:علم:I:11';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_8d21a7cc45be169d", "page": 2273, "quote": "غفر له ذنبه ... He (God) covered his sin ... forgave it"}, {"source": "fayyumi_misbah_munir", "block_id": "blk_msb_7833c08efd546919", "page": 2212, "quote": "غَفَرَ اللَّهُ لَهُ غَفْرًا ... وَغُفْرَانًا صَفَحَ عَنْه"}, {"source": "jawhari_sihah", "block_id": "blk_sih_1bc77a4aec5a1e93", "page": 1528, "quote": "فَغَفَرَ له ذنبه مَغْفِرَةً وغَفْراً وغُفْرانا"}]')) WHERE id = 'TDY:QR:SP:SV:غفر:I:12';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_2855e2f2dfc64001", "page": 1132, "quote": "واللَّه عَزَّ وَجَلَّ يَقْبَلُ الأَعمال مِنْ عِبَادِهِ وَعَنْهُمْ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_a98aa671ca3e65a5", "page": 653, "quote": "وَلا يُقْبَلُ مِنْها عَدْلٌ"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_0cb61b98e8d8669c", "page": 209, "quote": "إنّما يَتَقَبَّلُ اللهُ من المُتَّقين"}]')) WHERE id = 'TDY:QR:SP:SV:قبل:I:13';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_2855e2f2dfc64001", "page": 1132, "quote": "يَقْبَلُ الأَعمال مِنْ عِبَادِهِ وَعَنْهُمْ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_ecdb287599252f9b", "page": 653, "quote": "وقَبِلْتُ عذره وتوبته وغيره"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_0cb61b98e8d8669c", "page": 209, "quote": "وَهُوَ الَّذِي يَقْبَلُ التَّوبةَ عَن عبادِه"}]'), '$.plain_en', 'to accept (repentance) from someone', '$.note_en', 'Lisān treats مِنْ and عَنْ alike here.') WHERE id = 'TDY:QR:SP:SV:قبل:I:14';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_79c3b2acfeb750c2", "page": 799, "quote": "النُّزُولُ في الأصل هو انحِطَاطٌ من عُلْو"}, {"source": "fayyumi_misbah_munir", "block_id": "blk_msb_519bf288cdf8cbc4", "page": 3044, "quote": "نَزَلَ مِنْ عُلْوٍ إلَى سُفْلٍ"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_f7225aaec97b73eb", "page": 3765, "quote": "ونَزَلَ مِنْ عُلْوٍ إِلى سُفْل: انْحَدَر"}]')) WHERE id = 'TDY:QR:SP:SV:نزل:II:1';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "fayyumi_misbah_munir", "block_id": "blk_msb_519bf288cdf8cbc4", "page": 3044, "quote": "وَيَتَعَدَّى بِالْحَرْفِ وَالْهَمْزَةِ وَالتَّضْعِيفِ فَيُقَالُ نَزَلْتُ بِه"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_28ab01f51759d9e2", "page": 799, "quote": "نَزَلَ الله بكذا ... قال: نَزَلَ بِهِ الرُّوحُ الْأَمِين"}]'), '$.note_en', 'From tafsīr: no lexicon covers this بِ in 7:33 (سلطانًا is the object). The books have نزل بِه only for Form I, "brought it down".') WHERE id = 'TDY:QR:SP:SV:نزل:II:2';
